template<typename Trav, typename Func>
inline void omp_trav_for_each(const Trav &trav, const Func &f) {
#ifdef _OPENMP
	#pragma omp parallel for schedule(static)
#endif
	for (auto sub_trav : trav) {
		sub_trav.for_each(f);
	}
}

