	// processes a subset of rows, and inside each row we traverse all 'j'
	// with a Noarr for_each.
	auto row_range = full_trav.template range<'i'>();

	#pragma omp parallel for schedule(static)
	for (std::size_t r = 0; r < row_range.size(); ++r) {
