		auto [i, j] = get_indices<'i', 'j'>(state);

		A[state] = ( (num_t)i * (num_t)(j + 2) + (num_t)2 ) * inv_n;
		B[state] = ( (num_t)i * (num_t)(j + 3) + (num_t)3 ) * inv_n;
	});
#endif
