			// (j inner, i outer) and `a_layout = j_vec ^ i_vec`, the top-most
			// dimension here is 'i'. Iterating over `travA` therefore gives
			// one row (fixed i) per iteration.
			auto travA = traverser(A).order(interior);

			// Parallelize over rows. Each iteration of the range-based loop
			// gets a traverser with 'i' fixed and traverses 'j' in-order.
#pragma omp parallel for schedule(static)
			for (auto row_trav : travA) {
				row_trav.for_each([&](auto state) {
					// Compute neighbor states in the 4 cardinal directions.
					// These are pure state arithmetic operations; they do not
					// change the underlying data, only the logical indices.
					auto west  = state - idx<'j'>(1);
					auto east  = state + idx<'j'>(1);
					auto south = state + idx<'i'>(1);
					auto north = state - idx<'i'>(1);

					B[state] = factor * (A[state] + A[west] + A[east] + A[south] + A[north]);
				});
			}
		}

		// -----------------------------------------------------------------
		// Second sweep: A := stencil(B)
		// -----------------------------------------------------------------
		{
			auto travB = traverser(B).order(interior);

#pragma omp parallel for schedule(static)
			for (auto row_trav : travB) {
				row_trav.for_each([&](auto state) {
					auto west  = state - idx<'j'>(1);
					auto east  = state + idx<'j'>(1);
					auto south = state + idx<'i'>(1);
					auto north = state - idx<'i'>(1);

					A[state] = factor * (B[state] + B[west] + B[east] + B[south] + B[north]);
				});
			}
		}
	}
#pragma endscop
}

} // namespace


int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t tsteps = TSTEPS;

	// set lengths of dimensions
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	// allocate data
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// initialize arrays
	init_array(A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_jacobi_2d((int)tsteps, A.get_ref(), B.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (to prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'i'>());
