using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// A and B are N x N with C-style row-major layout: i = row, j = column
	// Layout: scalar ^ vector<'j'> ^ vector<'i'>
	// => 'i' is the outer (row) dimension, 'j' is the inner (contiguous) dimension
	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(b_layout, j_vec ^ i_vec);
} tuning;


// Array initialization
// Kept structurally identical, but we avoid recomputing the length in every iteration.
void init_array(auto A, auto B) {
	using namespace noarr;

	// A, B: i x j
	const std::size_t n = A | get_length<'i'>();

	traverser(A, B).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		// Same arithmetic as in the original code to preserve numerical behaviour
		A[state] = ((num_t)i * (num_t)(j + 2) + (num_t)2) / (num_t)n;
		B[state] = ((num_t)i * (num_t)(j + 3) + (num_t)3) / (num_t)n;
	});
}


// Main computational kernel
// Optimizations:
//  - keep row-major traversal (good spatial locality along 'j')
//  - restrict work to interior using slices
//  - parallelize over the outer ('i') dimension using OpenMP and traverser iterators
//  - precompute traversal of the interior region and reuse it in both sweeps
[[gnu::flatten, gnu::noinline]]
void kernel_jacobi_2d(int tsteps, auto A, auto B) {
	using namespace noarr;

	// A, B: i x j
	const std::size_t n = A | get_length<'i'>();
	// number of interior points in each dimension (excluding boundaries at 0 and n-1)
	const std::size_t inner_len = n - 2;

	// Constant stencil weight (exactly the same constant as in the original code)
	const num_t w = (num_t)0.2;

	// Proto-structure describing the interior region in both dimensions.
	// We slice out i ∈ [1, n-1) and j ∈ [1, n-1).
	auto interior_region =
		noarr::slice<'i'>(1, inner_len) ^
		noarr::slice<'j'>(1, inner_len);

#pragma scop
	for (int t = 0; t < tsteps; t++) {
		// ---------------------------------------------------------------------
		// First sweep: B := stencil(A)
		// ---------------------------------------------------------------------
		// Traverser over the interior of A. We keep the data layout unchanged
		// and only restrict the set of visited indices.
		auto trav_A = traverser(A).order(interior_region);

		// Parallelize over the outer ('i') dimension using the traverser
		// iterator: each iteration of the OpenMP loop gets one row (fixed 'i')
		// and then iterates over all interior columns 'j' of that row.
		#pragma omp parallel for schedule(static)
		for (auto trav_row : trav_A) {
			trav_row.for_each([&](auto state) {
				// state has the current interior (i, j)
				// Use state arithmetic (on states, not traversers) to obtain
				// the 4-point von Neumann neighbourhood.
				auto west  = state - idx<'j'>(1); // (i, j-1)
				auto east  = state + idx<'j'>(1); // (i, j+1)
				auto south = state + idx<'i'>(1); // (i+1, j)
				auto north = state - idx<'i'>(1); // (i-1, j)

				// Load centre once to reduce redundant reads; the order of
				// summation is kept the same as in the original expression.
				const num_t center = A[state];

				B[state] = w * (center + A[west] + A[east] + A[south] + A[north]);
			});
		}

		// ---------------------------------------------------------------------
		// Second sweep: A := stencil(B)
		// ---------------------------------------------------------------------
		// Exactly the same pattern, but swapping roles of A and B.
		auto trav_B = traverser(B).order(interior_region);

		#pragma omp parallel for schedule(static)
		for (auto trav_row : trav_B) {
			trav_row.for_each([&](auto state) {
				auto west  = state - idx<'j'>(1);
				auto east  = state + idx<'j'>(1);
				auto south = state + idx<'i'>(1);
				auto north = state - idx<'i'>(1);

				const num_t center = B[state];

				A[state] = w * (center + B[west] + B[east] + B[south] + B[north]);
			});
		}
	}
#pragma endscop
}

} // namespace


